#!/usr/bin/env bash
# Mirror Mind hook wrapper — GENERATED by scripts/generate_hook_wrappers.sh.
# Edit the generator, never this file: every agy wrapper shares these bytes
# and differs only in the hook name and its stdin gate (CV21.DS7.TS2).
set -uo pipefail
HOOK="agy:stop"
GATE=''

# agy sends the payload on stdin and blocks its agent loop on this process.
# Read the payload once; when the gate says this invocation is not ours,
# answer the empty object without resolving Node at all.
PAYLOAD="$(cat 2>/dev/null || true)"
if [ -n "$GATE" ] && printf '%s' "$PAYLOAD" | grep -qE "$GATE"; then
  printf '{}\n'
  exit 0
fi

# This wrapper is the Claude plugin's, and a plugin is copied into Claude
# Code's own cache: no relative path from here reaches the Mirror tree. It
# runs the installed `mirror-hook` bin instead, and reads no tree .env.
REPO_ROOT=""

# A hook never fails the user's turn, and never fails in silence: when it
# cannot do its job it appends ONE line to <mirror home>/hooks.log and exits
# 0 — after answering agy's contract, so the agent loop never stalls.
env_file_value() {
  [ -f "$2" ] || return 0
  sed -n -E "s/^[[:space:]]*(export[[:space:]]+)?$1[[:space:]]*=[[:space:]]*//p" "$2" \
    | tail -n 1 | tr -d "\"'\r"
}
env_value() {
  local value=""
  if [ -n "${!1+set}" ]; then printf '%s' "${!1}"; return; fi
  [ -z "$REPO_ROOT" ] || value="$(env_file_value "$1" "$REPO_ROOT/.env")"
  [ -n "$value" ] || value="$(env_file_value "$1" "${XDG_CONFIG_HOME:-$HOME/.config}/mirror/env")"
  printf '%s' "$value"
}
note() {
  local home user
  home="$(env_value MIRROR_HOME)"
  user="$(env_value MIRROR_USER)"
  if [ -n "$home" ]; then
    home="${home/#\~/$HOME}"
  elif [ -n "$user" ]; then
    home="$HOME/.mirror-minds/$user"
    [ -d "$home" ] || [ ! -d "$HOME/.mirror/$user" ] || home="$HOME/.mirror/$user"
  else
    return 0
  fi
  mkdir -p "$home" 2>/dev/null \
    && printf '%s %s: %s\n' "$(date -u +%Y-%m-%dT%H:%M:%SZ)" "$HOOK" "$1" >> "$home/hooks.log" 2>/dev/null
}

# Find the bin. MIRROR_BIN names the directory holding `mirror` and
# `mirror-hook` (`$(npm prefix -g)/bin`), the same trust class as MIRROR_NODE;
# then the PATH; then the global bin directories a GUI launch leaves off it.
ENTRY=""
[ -n "${MIRROR_BIN:-}" ] && [ -x "$MIRROR_BIN/mirror-hook" ] && ENTRY="$MIRROR_BIN/mirror-hook"
[ -n "$ENTRY" ] || ENTRY="$(command -v mirror-hook 2>/dev/null || true)"
for candidate in "$HOME/.nvm/current/bin" /opt/homebrew/bin /usr/local/bin; do
  [ -n "$ENTRY" ] && break
  [ -x "$candidate/mirror-hook" ] && ENTRY="$candidate/mirror-hook"
done
# On Windows npm writes no symlink: the `mirror-hook` in its global prefix is
# a POSIX shell shim, and `node_modules/` sits beside it. Node cannot run the
# shim ("node exited 1" in hooks.log on every hook); the entry it wraps is the
# package's own bin, so that is the entry when it is there. A POSIX prefix
# keeps node_modules under lib/ and its bin is already the .js: no change.
shim_entry=""
[ -n "$ENTRY" ] && shim_entry="$(dirname "$ENTRY")/node_modules/mirror-mind/bin/mirror-hook.js"
[ -n "$shim_entry" ] && [ -f "$shim_entry" ] && ENTRY="$shim_entry"

if [ -z "$ENTRY" ]; then
  note "mirror-hook not found on PATH; hook skipped. Install mirror-mind (npm install -g mirror-mind) or set MIRROR_BIN to its bin directory."
  exit 0
fi

NODE="${MIRROR_NODE:-}"
if [ -z "$NODE" ] || [ ! -x "$NODE" ]; then
  NODE="$(command -v node 2>/dev/null || true)"
fi
for candidate in "$(dirname "$ENTRY")/node" "$HOME/.nvm/current/bin/node" /opt/homebrew/bin/node /usr/local/bin/node; do
  [ -n "$NODE" ] && break
  [ -x "$candidate" ] && NODE="$candidate"
done

if [ -z "$NODE" ]; then
  printf '{}\n'
  note "node not found on PATH; hook skipped. Set MIRROR_NODE."
  exit 0
fi

# The payload was consumed by the gate read; re-feed it to the entry.
printf '%s' "$PAYLOAD" | "$NODE" "$ENTRY" "$HOOK" "$@"
status=$?
if [ "$status" -ne 0 ]; then
  printf '{}\n'
  note "node exited $status before the hook finished ($NODE, $("$NODE" --version 2>/dev/null || echo 'version unknown')); Mirror needs Node 24 or later. Set MIRROR_NODE."
fi
exit 0
